#include "emitter.h"

#include <cstdio>
#include <fstream>

namespace vc3 {
namespace fs = std::filesystem;

namespace {

const char* source_str(Function::Source s) {
    switch (s) {
        case Function::Source::Entry: return "entry";
        case Function::Source::CallTarget: return "call";
        case Function::Source::PointerScan: return "ptrscan";
        case Function::Source::ImmediateRef: return "immref";
        case Function::Source::Manual: return "manual";
    }
    return "?";
}

constexpr const char* kPreamble =
    "// Generated by vc3recomp — do not edit.\n"
    "#include \"vc3/helpers.h\"\n"
    "#include \"decls.h\"\n"
    "using vc3::u8; using vc3::u16; using vc3::u32; using vc3::u64;\n"
    "using vc3::s8; using vc3::s16; using vc3::s32; using vc3::s64;\n\n";

}  // namespace

LiftStats emit(const Xbe& xbe, const Analyzer& an, const EmitOptions& opts) {
    fs::create_directories(opts.out_dir);
    const auto& funcs = an.functions();
    LiftStats stats;

    // Remove stale outputs so CMake's glob doesn't pick up old files.
    for (const auto& e : fs::directory_iterator(opts.out_dir))
        if (e.path().extension() == ".cpp") fs::remove(e.path());

    {
        std::ofstream h(opts.out_dir / "decls.h");
        h << "// Generated by vc3recomp — do not edit.\n#pragma once\n#include \"vc3/recomp.h\"\n\n";
        for (const auto& [va, f] : funcs) h << "void " << fn_name(va) << "(vc3::Cpu&);\n";
    }

    size_t idx = 0, file_no = 0;
    std::ofstream out;
    for (const auto& [va, f] : funcs) {
        if (idx++ % opts.funcs_per_file == 0) {
            char name[32];
            std::snprintf(name, sizeof name, "funcs_%03zu.cpp", file_no++);
            out = std::ofstream(opts.out_dir / name);
            out << kPreamble;
        }
        out << "// " << source_str(f.source) << ", " << f.insns.size() << " insns\n";
        out << lift_function(an, f, stats) << "\n";
    }
    out.close();

    std::ofstream tbl(opts.out_dir / "func_table.cpp");
    tbl << "// Generated by vc3recomp — do not edit.\n#include \"decls.h\"\n\n";
    tbl << "const vc3::FuncEntry vc3_func_table[] = {\n";
    for (const auto& [va, f] : funcs) {
        char line[64];
        std::snprintf(line, sizeof line, "    {0x%08x, %s},\n", va, fn_name(va).c_str());
        tbl << line;
    }
    tbl << "};\nconst size_t vc3_func_table_size = " << funcs.size() << ";\n";
    char ep[64];
    std::snprintf(ep, sizeof ep, "const uint32_t vc3_entry_point = 0x%08x;\n", xbe.entry);
    tbl << ep;

    std::ofstream lst(opts.out_dir / "functions.txt");
    lst << "# addr     source   insns blocks tailcalls jumptables flags\n";
    for (const auto& [va, f] : funcs) {
        char line[160];
        std::snprintf(line, sizeof line, "%08x %-8s %6zu %6zu %9zu %10zu %s\n", va, source_str(f.source),
                      f.insns.size(), f.block_starts.size(), f.tail_calls.size(), f.jump_tables.size(),
                      f.decode_error ? "decode_error" : "");
        lst << line;
    }
    return stats;
}

}  // namespace vc3
